import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiPlay,
  FiVideo,
  FiEye,
  FiStar,
  FiGrid,
  FiCalendar,
  FiExternalLink,
} from 'react-icons/fi';

import api from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


// ==========================================
// ADMIN VIDEOS
// ==========================================

const AdminVideos = () => {

  // ========================================
  // LANGUAGE
  // ========================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km';


  // ========================================
  // STATE
  // ========================================

  const [
    videos,
    setVideos,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    modalOpen,
    setModalOpen,
  ] = useState(false);


  const [
    editingVideo,
    setEditingVideo,
  ] = useState(null);


  const [
    submitting,
    setSubmitting,
  ] = useState(false);


  const [
    formData,
    setFormData,
  ] = useState({
    title: '',
    description: '',
    video_url: '',
    thumbnail: '',
    category: '',
    date: '',
    is_featured: false,
  });


  // ========================================
  // CATEGORIES
  // ========================================

  const categories = [
    {
      value: 'School Activities',
      label: t(
        'videosPage.categoriesList.schoolActivities'
      ),
    },
    {
      value: 'Classroom',
      label: t(
        'videosPage.categoriesList.classroom'
      ),
    },
    {
      value: 'Graduation',
      label: t(
        'videosPage.categoriesList.graduation'
      ),
    },
    {
      value: 'Trips',
      label: t(
        'videosPage.categoriesList.trips'
      ),
    },
    {
      value: 'Special Events',
      label: t(
        'videosPage.categoriesList.specialEvents'
      ),
    },
  ];


  // ========================================
  // GET CATEGORY LABEL
  // ========================================

  const getCategoryLabel = (
    value
  ) => {

    if (!value) {
      return '-';
    }


    const category =
      categories.find(
        (item) =>
          item.value === value
      );


    return category
      ? category.label
      : value;

  };


  // ========================================
  // FETCH VIDEOS
  // ========================================

  useEffect(() => {

    fetchVideos();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const fetchVideos = async () => {

    try {

      setLoading(true);


      const response =
        await api.get(
          '/api/videos/'
        );


      setVideos(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch videos error:',
        error
      );


      toast.error(
        error.response?.data?.detail ||
        t(
          'videosPage.loadFailed'
        )
      );

    } finally {

      setLoading(false);

    }

  };


  // ========================================
  // RESET FORM
  // ========================================

  const resetForm = () => {

    setEditingVideo(null);


    setFormData({
      title: '',
      description: '',
      video_url: '',
      thumbnail: '',
      category: '',
      date: '',
      is_featured: false,
    });

  };


  // ========================================
  // OPEN ADD MODAL
  // ========================================

  const handleAdd = () => {

    resetForm();

    setModalOpen(true);

  };


  // ========================================
  // CLOSE MODAL
  // ========================================

  const handleCloseModal = () => {

    setModalOpen(false);

    resetForm();

  };


  // ========================================
  // GET YOUTUBE ID
  // ========================================

  const getYoutubeId = (
    url
  ) => {

    if (!url) {
      return null;
    }


    try {

      const cleanUrl =
        url.trim();


      if (
        cleanUrl.includes(
          'youtube.com/watch'
        )
      ) {

        const parsedUrl =
          new URL(cleanUrl);


        return (
          parsedUrl.searchParams.get(
            'v'
          )
        );

      }


      if (
        cleanUrl.includes(
          'youtu.be/'
        )
      ) {

        return cleanUrl
          .split('youtu.be/')[1]
          ?.split('?')[0]
          ?.split('&')[0];

      }


      if (
        cleanUrl.includes(
          'youtube.com/shorts/'
        )
      ) {

        return cleanUrl
          .split(
            'youtube.com/shorts/'
          )[1]
          ?.split('?')[0]
          ?.split('&')[0];

      }


      if (
        cleanUrl.includes(
          'youtube.com/embed/'
        )
      ) {

        return cleanUrl
          .split(
            'youtube.com/embed/'
          )[1]
          ?.split('?')[0]
          ?.split('&')[0];

      }


      return null;

    } catch (error) {

      console.error(
        'YouTube ID error:',
        error
      );


      return null;

    }

  };


  // ========================================
  // GENERATE YOUTUBE THUMBNAIL
  // ========================================

  const getYoutubeThumbnail = (
    url
  ) => {

    const youtubeId =
      getYoutubeId(url);


    if (!youtubeId) {

      return '';

    }


    return (
      `https://img.youtube.com/vi/${youtubeId}/hqdefault.jpg`
    );

  };


  // ========================================
  // GET TABLE THUMBNAIL
  // ========================================

  const getThumbnail = (
    video
  ) => {

    if (!video) {

      return '';

    }


    if (
      video.thumbnail?.trim()
    ) {

      const customThumbnail =
        video.thumbnail.trim();


      const thumbnailYoutubeId =
        getYoutubeId(
          customThumbnail
        );


      if (thumbnailYoutubeId) {

        return (
          `https://img.youtube.com/vi/${thumbnailYoutubeId}/hqdefault.jpg`
        );

      }


      return customThumbnail;

    }


    if (
      video.thumbnail_url?.trim()
    ) {

      const customThumbnail =
        video.thumbnail_url.trim();


      const thumbnailYoutubeId =
        getYoutubeId(
          customThumbnail
        );


      if (thumbnailYoutubeId) {

        return (
          `https://img.youtube.com/vi/${thumbnailYoutubeId}/hqdefault.jpg`
        );

      }


      return customThumbnail;

    }


    return getYoutubeThumbnail(
      video.video_url
    );

  };


  // ========================================
  // GET FORM THUMBNAIL
  // ========================================

  const getFormThumbnail = () => {

    if (
      formData.thumbnail?.trim()
    ) {

      const customThumbnail =
        formData.thumbnail.trim();


      const thumbnailYoutubeId =
        getYoutubeId(
          customThumbnail
        );


      if (thumbnailYoutubeId) {

        return (
          `https://img.youtube.com/vi/${thumbnailYoutubeId}/hqdefault.jpg`
        );

      }


      return customThumbnail;

    }


    return getYoutubeThumbnail(
      formData.video_url
    );

  };


  // ========================================
  // FORMAT DATE
  // ========================================

  const formatDate = (
    date
  ) => {

    if (!date) {

      return '-';

    }


    try {

      const dateOnly =
        String(date).slice(
          0,
          10
        );


      const parts =
        dateOnly.split('-');


      if (
        parts.length === 3
      ) {

        const [
          year,
          month,
          day,
        ] = parts;


        return (
          `${day}/${month}/${year}`
        );

      }


      const parsed =
        new Date(date);


      if (
        Number.isNaN(
          parsed.getTime()
        )
      ) {

        return '-';

      }


      return parsed.toLocaleDateString(
        isKhmer
          ? 'km-KH'
          : 'en-GB'
      );

    } catch {

      return '-';

    }

  };


  // ========================================
  // SUBMIT
  // ========================================

  const handleSubmit = async (
    e
  ) => {

    e.preventDefault();


    if (
      !formData.title.trim()
    ) {

      toast.error(
        t(
          'videosPage.titleRequired'
        )
      );

      return;

    }


    if (
      !formData.video_url.trim()
    ) {

      toast.error(
        t(
          'videosPage.videoUrlRequired'
        )
      );

      return;

    }


    if (!formData.date) {

      toast.error(
        t(
          'videosPage.dateRequired'
        )
      );

      return;

    }


    try {

      setSubmitting(true);


      const payload = {

        title:
          formData.title.trim(),

        description:
          formData.description?.trim() ||
          '',

        video_url:
          formData.video_url.trim(),

        thumbnail:
          formData.thumbnail?.trim() ||
          '',

        category:
          formData.category ||
          '',

        date:
          formData.date,

        is_featured:
          Boolean(
            formData.is_featured
          ),

      };


      console.log(
        'Video payload:',
        payload
      );


      if (editingVideo) {

        await api.put(
          `/api/videos/${editingVideo.id}`,
          payload
        );


        toast.success(
          t(
            'videosPage.updatedSuccess'
          )
        );

      } else {

        await api.post(
          '/api/videos/',
          payload
        );


        toast.success(
          t(
            'videosPage.addedSuccess'
          )
        );

      }


      handleCloseModal();


      await fetchVideos();

    } catch (error) {

      console.error(
        'Video operation error:',
        error
      );


      console.error(
        'Backend response:',
        error.response?.data
      );


      let message =
        t(
          'videosPage.operationFailed'
        );


      const detail =
        error.response?.data?.detail;


      if (
        typeof detail ===
        'string'
      ) {

        message = detail;

      } else if (
        Array.isArray(detail)
      ) {

        message = detail
          .map((item) => {

            const field =
              item?.loc?.[
                item.loc.length - 1
              ];


            return (
              `${field || t(
                'videosPage.field'
              )}: ${
                item?.msg ||
                t(
                  'videosPage.invalidValue'
                )
              }`
            );

          })
          .join(', ');

      }


      toast.error(message);

    } finally {

      setSubmitting(false);

    }

  };


  // ========================================
  // EDIT
  // ========================================

  const handleEdit = (
    video
  ) => {

    setEditingVideo(
      video
    );


    setFormData({

      title:
        video.title || '',

      description:
        video.description || '',

      video_url:
        video.video_url || '',

      thumbnail:
        video.thumbnail ||
        video.thumbnail_url ||
        '',

      category:
        video.category || '',

      date:
        video.date
          ? String(
              video.date
            ).slice(
              0,
              10
            )
          : '',

      is_featured:
        Boolean(
          video.is_featured
        ),

    });


    setModalOpen(true);

  };


  // ========================================
  // DELETE
  // ========================================

  const handleDelete = async (
    id
  ) => {

    const confirmed =
      window.confirm(
        t(
          'videosPage.deleteConfirm'
        )
      );


    if (!confirmed) {

      return;

    }


    try {

      await api.delete(
        `/api/videos/${id}`
      );


      toast.success(
        t(
          'videosPage.deletedSuccess'
        )
      );


      await fetchVideos();

    } catch (error) {

      console.error(
        'Delete video error:',
        error
      );


      toast.error(
        error.response?.data?.detail ||
        t(
          'videosPage.deleteFailed'
        )
      );

    }

  };


  // ========================================
  // OPEN VIDEO
  // ========================================

  const handleOpenVideo = (
    url
  ) => {

    if (!url) {

      return;

    }


    window.open(
      url,
      '_blank',
      'noopener,noreferrer'
    );

  };


  // ========================================
  // SUMMARY
  // ========================================

  const featuredCount =
    videos.filter(
      (video) =>
        video.is_featured
    ).length;


  const totalViews =
    videos.reduce(
      (total, video) =>
        total +
        Number(
          video.views || 0
        ),
      0
    );


  const categoryCount =
    new Set(
      videos
        .map(
          (video) =>
            video.category
        )
        .filter(Boolean)
    ).size;


  // ========================================
  // TABLE COLUMNS
  // ========================================

  const columns = [

    {
      key: 'thumbnail',

      label:
        t(
          'videosPage.video'
        ),

      render: (_, row) => {

        const thumbnail =
          getThumbnail(row);


        return (

          <div
            className="
              relative

              w-[105px]
              h-[62px]

              bg-blue-50

              rounded-lg

              overflow-hidden

              flex-shrink-0

              group
            "
          >

            {
              thumbnail ? (

                <img
                  src={thumbnail}

                  alt={
                    row.title ||
                    t(
                      'videosPage.video'
                    )
                  }

                  className="
                    w-full
                    h-full
                    object-cover
                  "

                  onError={(e) => {

                    e.currentTarget.style.display =
                      'none';

                  }}
                />

              ) : (

                <div
                  className="
                    w-full
                    h-full

                    flex
                    items-center
                    justify-center

                    text-blue-300
                  "
                >

                  <FiVideo
                    size={22}
                  />

                </div>

              )
            }


            <button
              type="button"

              onClick={() =>
                handleOpenVideo(
                  row.video_url
                )
              }

              title={
                t(
                  'videosPage.watchVideo'
                )
              }

              className="
                absolute
                inset-0

                bg-black/20

                flex
                items-center
                justify-center

                opacity-0

                group-hover:opacity-100

                transition
              "
            >

              <div
                className="
                  w-8
                  h-8

                  bg-red-600
                  text-white

                  rounded-full

                  flex
                  items-center
                  justify-center

                  shadow
                "
              >

                <FiPlay
                  size={14}
                  className="ml-0.5"
                />

              </div>

            </button>

          </div>

        );

      },
    },


    {
      key: 'title',

      label:
        t(
          'videosPage.titleColumn'
        ),

      render: (
        val,
        row
      ) => (

        <div
          className="
            max-w-[240px]
          "
        >

          <div
            className="
              flex
              items-center
              gap-2
            "
          >

            <p
              className="
                font-semibold
                text-blue-900
                truncate
              "
            >

              {
                val ||
                t(
                  'videosPage.untitled'
                )
              }

            </p>


            {
              row.is_featured && (

                <FiStar
                  size={13}

                  className="
                    text-red-600
                    fill-current
                    flex-shrink-0
                  "
                />

              )
            }

          </div>


          {
            row.description && (

              <p
                className="
                  text-xs
                  text-blue-400
                  truncate
                  mt-1
                "
              >

                {row.description}

              </p>

            )
          }

        </div>

      ),
    },


    {
      key: 'category',

      label:
        t(
          'videosPage.category'
        ),

      render: (val) =>
        val ? (

          <span
            className="
              inline-flex

              px-2.5
              py-1

              bg-blue-50
              text-blue-900

              rounded-full

              text-[11px]
              font-semibold

              whitespace-nowrap
            "
          >

            {
              getCategoryLabel(
                val
              )
            }

          </span>

        ) : (

          <span
            className="
              text-blue-300
            "
          >
            -
          </span>

        ),
    },


    {
      key: 'date',

      label:
        t(
          'videosPage.date'
        ),

      render: (val) => (

        <div
          className="
            flex
            items-center
            gap-1.5

            text-sm
            text-blue-500

            whitespace-nowrap
          "
        >

          <FiCalendar
            size={13}
            className="text-red-600"
          />


          {formatDate(val)}

        </div>

      ),
    },


    {
      key: 'views',

      label:
        t(
          'videosPage.views'
        ),

      render: (val) => (

        <div
          className="
            inline-flex
            items-center
            gap-1.5

            text-sm
            text-blue-500
          "
        >

          <FiEye
            size={14}
            className="text-blue-300"
          />


          {
            Number(
              val || 0
            ).toLocaleString(
              isKhmer
                ? 'km-KH'
                : 'en-GB'
            )
          }

        </div>

      ),
    },


    {
      key: 'actions',

      label:
        t(
          'common.actions'
        ),

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleOpenVideo(
                row.video_url
              )
            }

            className="
              w-8
              h-8

              flex
              items-center
              justify-center

              bg-blue-50
              text-blue-600

              rounded-lg

              hover:bg-blue-600
              hover:text-white

              transition
            "

            title={
              t(
                'videosPage.watchVideo'
              )
            }
          >

            <FiPlay
              size={14}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleEdit(row)
            }

            className="
              w-8
              h-8

              flex
              items-center
              justify-center

              bg-blue-50
              text-blue-900

              rounded-lg

              hover:bg-blue-900
              hover:text-white

              transition
            "

            title={
              t(
                'videosPage.editVideo'
              )
            }
          >

            <FiEdit2
              size={14}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            className="
              w-8
              h-8

              flex
              items-center
              justify-center

              bg-red-50
              text-red-600

              rounded-lg

              hover:bg-red-600
              hover:text-white

              transition
            "

            title={
              t(
                'videosPage.deleteVideo'
              )
            }
          >

            <FiTrash2
              size={14}
            />

          </button>

        </div>

      ),
    },

  ];


  // ========================================
  // FORM THUMBNAIL
  // ========================================

  const formThumbnail =
    getFormThumbnail();


  // ========================================
  // RETURN
  // ========================================

  return (

    <div
      className={`
        w-full

        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >


      {/* ====================================
          HEADER
      ==================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row

          sm:items-center
          sm:justify-between

          gap-4

          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10

              bg-blue-900
              text-white

              rounded-xl

              flex
              items-center
              justify-center

              shadow-sm
            "
          >

            <FiVideo
              size={18}
            />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl

                font-bold
                text-blue-900
              "
            >

              {t(
                'videosPage.title'
              )}

            </h1>


            <p
              className="
                text-xs
                md:text-sm

                text-blue-400

                mt-1
              "
            >

              {t(
                'videosPage.subtitle'
              )}

            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            handleAdd
          }

          className="
            h-10
            px-4

            inline-flex
            items-center
            justify-center
            gap-2

            bg-red-600
            text-white

            rounded-lg

            text-sm
            font-semibold

            shadow-sm

            hover:bg-red-700
            hover:shadow-md

            transition-all
          "
        >

          <FiPlus
            size={17}
          />


          {t(
            'videosPage.addVideo'
          )}

        </button>

      </div>


      {/* ====================================
          SUMMARY CARDS
      ==================================== */}

      <div
        className="
          grid
          grid-cols-2
          xl:grid-cols-4

          gap-3

          mb-6
        "
      >

        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-xl

            p-4

            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >

                {t(
                  'videosPage.totalVideos'
                )}

              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >

                {videos.length}

              </p>

            </div>


            <div
              className="
                w-10
                h-10

                bg-blue-50
                text-blue-900

                rounded-lg

                flex
                items-center
                justify-center
              "
            >

              <FiVideo
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white

            border
            border-red-100

            rounded-xl

            p-4

            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >

                {t(
                  'videosPage.featured'
                )}

              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >

                {featuredCount}

              </p>

            </div>


            <div
              className="
                w-10
                h-10

                bg-red-50
                text-red-600

                rounded-lg

                flex
                items-center
                justify-center
              "
            >

              <FiStar
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-xl

            p-4

            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >

                {t(
                  'videosPage.totalViews'
                )}

              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >

                {
                  totalViews
                    .toLocaleString(
                      isKhmer
                        ? 'km-KH'
                        : 'en-GB'
                    )
                }

              </p>

            </div>


            <div
              className="
                w-10
                h-10

                bg-blue-50
                text-blue-600

                rounded-lg

                flex
                items-center
                justify-center
              "
            >

              <FiEye
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-xl

            p-4

            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >

                {t(
                  'videosPage.categories'
                )}

              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >

                {categoryCount}

              </p>

            </div>


            <div
              className="
                w-10
                h-10

                bg-blue-50
                text-blue-600

                rounded-lg

                flex
                items-center
                justify-center
              "
            >

              <FiGrid
                size={18}
              />

            </div>

          </div>

        </div>

      </div>


      {/* ====================================
          TABLE
      ==================================== */}

      <AdminCard
        className="
          border
          border-blue-200

          rounded-xl

          shadow-sm

          overflow-hidden
        "
      >

        <div
          className="
            px-5
            py-4

            border-b
            border-blue-200

            flex
            items-center
            justify-between
          "
        >

          <div>

            <h2
              className="
                text-sm
                font-bold
                text-blue-900
              "
            >

              {t(
                'videosPage.allVideos'
              )}

            </h2>


            <p
              className="
                text-xs
                text-blue-300
                mt-1
              "
            >

              {videos.length}{' '}

              {
                videos.length === 1
                  ? t(
                      'videosPage.videoFound'
                    )
                  : t(
                      'videosPage.videosFound'
                    )
              }

            </p>

          </div>

        </div>


        <AdminTable
          columns={columns}
          data={videos}
          loading={loading}
        />

      </AdminCard>


      {/* ====================================
          MODAL
      ==================================== */}

      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          handleCloseModal
        }

        title={
          editingVideo
            ? t(
                'videosPage.editVideo'
              )
            : t(
                'videosPage.addVideo'
              )
        }
      >

        <div
          className={
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        >

          <form
            onSubmit={
              handleSubmit
            }
          >

            <div className="space-y-4">


              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >

                  {t(
                    'videosPage.videoTitle'
                  )}


                  <span
                    className="
                      text-red-600
                    "
                  >
                    {' '}*
                  </span>

                </label>


                <input
                  type="text"

                  value={
                    formData.title
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      title:
                        e.target.value,
                    })
                  }

                  placeholder={
                    t(
                      'videosPage.titlePlaceholder'
                    )
                  }

                  className="
                    w-full
                    h-11

                    px-3.5

                    border
                    border-blue-200

                    rounded-lg

                    text-sm
                    text-blue-900

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition
                  "

                  required
                />

              </div>


              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >

                  {t(
                    'videosPage.description'
                  )}

                </label>


                <textarea
                  value={
                    formData.description
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      description:
                        e.target.value,
                    })
                  }

                  rows="3"

                  placeholder={
                    t(
                      'videosPage.descriptionPlaceholder'
                    )
                  }

                  className="
                    w-full

                    px-3.5
                    py-3

                    border
                    border-blue-200

                    rounded-lg

                    text-sm
                    text-blue-900

                    resize-none

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition
                  "
                />

              </div>


              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >

                  {t(
                    'videosPage.videoUrl'
                  )}


                  <span
                    className="
                      text-red-600
                    "
                  >
                    {' '}*
                  </span>

                </label>


                <div className="relative">

                  <input
                    type="url"

                    value={
                      formData.video_url
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,

                        video_url:
                          e.target.value,
                      })
                    }

                    placeholder="https://www.youtube.com/watch?v=..."

                    className="
                      w-full
                      h-11

                      pl-3.5
                      pr-10

                      border
                      border-blue-200

                      rounded-lg

                      text-sm
                      text-blue-900

                      outline-none

                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10

                      transition
                    "

                    required
                  />


                  <FiExternalLink
                    className="
                      absolute

                      right-3.5
                      top-1/2

                      -translate-y-1/2

                      text-blue-300
                    "
                  />

                </div>


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-1.5
                  "
                >

                  {t(
                    'videosPage.videoUrlHelp'
                  )}

                </p>

              </div>


              {
                formThumbnail && (

                  <div>

                    <label
                      className="
                        block
                        text-sm
                        font-semibold
                        text-blue-900
                        mb-1.5
                      "
                    >

                      {t(
                        'videosPage.thumbnailPreview'
                      )}

                    </label>


                    <div
                      className="
                        relative

                        w-full
                        h-[200px]

                        rounded-xl

                        overflow-hidden

                        bg-blue-50

                        group
                      "
                    >

                      <img
                        src={
                          formThumbnail
                        }

                        alt={
                          t(
                            'videosPage.thumbnailPreview'
                          )
                        }

                        className="
                          w-full
                          h-full
                          object-cover
                        "
                      />


                      <div
                        className="
                          absolute
                          inset-0

                          bg-black/20

                          flex
                          items-center
                          justify-center
                        "
                      >

                        <div
                          className="
                            w-12
                            h-12

                            bg-red-600
                            text-white

                            rounded-full

                            flex
                            items-center
                            justify-center

                            shadow-lg
                          "
                        >

                          <FiPlay
                            size={19}
                            className="ml-1"
                          />

                        </div>

                      </div>

                    </div>

                  </div>

                )
              }


              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >

                  {t(
                    'videosPage.thumbnailUrl'
                  )}

                </label>


                <input
                  type="url"

                  value={
                    formData.thumbnail
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      thumbnail:
                        e.target.value,
                    })
                  }

                  placeholder={
                    t(
                      'videosPage.thumbnailPlaceholder'
                    )
                  }

                  className="
                    w-full
                    h-11

                    px-3.5

                    border
                    border-blue-200

                    rounded-lg

                    text-sm
                    text-blue-900

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition
                  "
                />


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-1.5
                  "
                >

                  {t(
                    'videosPage.thumbnailHelp'
                  )}

                </p>

              </div>


              <div
                className="
                  grid
                  grid-cols-1
                  md:grid-cols-2
                  gap-4
                "
              >

                <div>

                  <label
                    className="
                      block
                      text-sm
                      font-semibold
                      text-blue-900
                      mb-1.5
                    "
                  >

                    {t(
                      'videosPage.category'
                    )}

                  </label>


                  <select
                    value={
                      formData.category
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,

                        category:
                          e.target.value,
                      })
                    }

                    className="
                      w-full
                      h-11

                      px-3.5

                      bg-white

                      border
                      border-blue-200

                      rounded-lg

                      text-sm
                      text-blue-900

                      outline-none

                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "
                  >

                    <option value="">

                      {t(
                        'videosPage.selectCategory'
                      )}

                    </option>


                    {
                      categories.map(
                        (category) => (

                          <option
                            key={
                              category.value
                            }

                            value={
                              category.value
                            }
                          >

                            {
                              category.label
                            }

                          </option>

                        )
                      )
                    }

                  </select>

                </div>


                <div>

                  <label
                    className="
                      block
                      text-sm
                      font-semibold
                      text-blue-900
                      mb-1.5
                    "
                  >

                    {t(
                      'videosPage.date'
                    )}


                    <span
                      className="
                        text-red-600
                      "
                    >
                      {' '}*
                    </span>

                  </label>


                  <input
                    type="date"

                    value={
                      formData.date
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,

                        date:
                          e.target.value,
                      })
                    }

                    className="
                      w-full
                      h-11

                      px-3.5

                      border
                      border-blue-200

                      rounded-lg

                      text-sm
                      text-blue-900

                      outline-none

                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "

                    required
                  />

                </div>

              </div>


              <label
                className={`
                  flex
                  items-center
                  gap-3

                  p-3.5

                  border

                  rounded-xl

                  cursor-pointer

                  transition-all

                  ${
                    formData.is_featured
                      ? `
                        border-red-300
                        bg-red-50
                      `
                      : `
                        border-blue-200
                        bg-white
                      `
                  }
                `}
              >

                <input
                  type="checkbox"

                  checked={
                    formData.is_featured
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      is_featured:
                        e.target.checked,
                    })
                  }

                  className="
                    w-4
                    h-4
                    accent-red-500
                  "
                />


                <div
                  className="
                    w-9
                    h-9

                    bg-red-100
                    text-red-600

                    rounded-lg

                    flex
                    items-center
                    justify-center
                  "
                >

                  <FiStar
                    size={16}
                  />

                </div>


                <div>

                  <p
                    className="
                      text-sm
                      font-semibold
                      text-blue-900
                    "
                  >

                    {t(
                      'videosPage.featuredVideo'
                    )}

                  </p>


                  <p
                    className="
                      text-[10px]
                      text-blue-300
                      mt-0.5
                    "
                  >

                    {t(
                      'videosPage.highlightVideo'
                    )}

                  </p>

                </div>

              </label>

            </div>


            <div
              className="
                mt-6
                pt-4

                border-t
                border-blue-200

                flex
                items-center
                justify-end

                gap-3
              "
            >

              <button
                type="button"

                onClick={
                  handleCloseModal
                }

                disabled={
                  submitting
                }

                className="
                  h-10

                  px-4

                  bg-white

                  border
                  border-blue-200

                  text-blue-400

                  rounded-lg

                  text-sm
                  font-semibold

                  hover:bg-blue-50

                  disabled:opacity-50

                  transition
                "
              >

                {t(
                  'common.cancel'
                )}

              </button>


              <button
                type="submit"

                disabled={
                  submitting
                }

                className="
                  min-w-[110px]
                  h-10

                  px-5

                  bg-red-600
                  text-white

                  rounded-lg

                  text-sm
                  font-semibold

                  hover:bg-red-700

                  disabled:opacity-50
                  disabled:cursor-not-allowed

                  transition
                "
              >

                {
                  submitting
                    ? editingVideo
                      ? t(
                          'videosPage.updating'
                        )
                      : t(
                          'videosPage.adding'
                        )
                    : editingVideo
                    ? t(
                        'videosPage.updateVideo'
                      )
                    : t(
                        'videosPage.addVideo'
                      )
                }

              </button>

            </div>

          </form>

        </div>

      </AdminModal>

    </div>

  );

};


export default AdminVideos;
